@startuml

class Resident {
  + Name : string
  + StreetAddress : string
  + PhoneNumber : string
  + Email : string
  + ItemsDescription : string
}

class PickupVehicle {
  + LicensePlateNumber : string
  + AvailableStorageSpace : int
  + Driver : VolunteerDriver
}

abstract class Employee {
  + FirstName : string
  + LastName : string
}

class DistributionCenterEmployee {}

class FoodBank {}

class VolunteerDriver {}

class Category {
  + Name : string
}

class Article {
  + RFIDTag : string
  + Description : string
  + Category : Category
}

PickupVehicle "1" -- "*" Resident : collectsFrom
DistributionCenterEmployee "1" -- "*" Article : examines
FoodBank "0..1" -- "*" Article : receivesNonPerishable
VolunteerDriver "1" -- "*" Article : delivers
Resident "1" -- "*" PickupRequest : makes
PickupVehicle "1" -- "*" PickupRoute : follows
DistributionCenterEmployee "1" -- "*" Article : assignsCategory
DistributionCenterEmployee "0..*" Client : contacts
Client "1" -- "*" Category : needs

@enduml

